<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_customer();
$cid=(int)$_SESSION['customer_id']; $errors=[]; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$text=trim((string)($_POST['message']??''));if($text==='')$errors[]='Write a message first.';elseif(mb_strlen($text)>4000)$errors[]='Message is too long.';else{$pdo->prepare("INSERT INTO customer_private_messages(customer_id,sender_type,sender_id,message,is_read) VALUES(?, 'CUSTOMER', ?, ?, 0)")->execute([$cid,$cid,$text]);$msg='Message sent privately to management.';}}
try{$pdo->prepare("UPDATE customer_private_messages SET is_read=1 WHERE customer_id=? AND sender_type='ADMIN'")->execute([$cid]);}catch(Throwable $ignore){}
try{$s=$pdo->prepare('SELECT * FROM customer_private_messages WHERE customer_id=? ORDER BY created_at ASC,message_id ASC');$s->execute([$cid]);$rows=$s->fetchAll();}catch(Throwable $e){$rows=[];}
$title='Private Chat'; require __DIR__.'/../includes/header.php';
?><div class="section-head"><div><span class="eyebrow">PRIVATE CUSTOMER SUPPORT</span><h1>Chat with Shadril</h1><p>This conversation is private between your account and store management.</p></div><a class="btn ghost" href="/customer/account.php">My account</a></div>
<?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?><?php foreach($errors as $x): ?><div class="errors"><?=e($x)?></div><?php endforeach; ?>
<section class="chat-shell panel"><div class="chat-head"><strong>Shadril Shopping Store Support</strong><span>Private conversation</span></div><div class="chat-messages"><?php foreach($rows as $r): ?><div class="chat-row <?=strtolower($r['sender_type'])==='customer'?'mine':'theirs'?>"><div class="chat-bubble"><small><?=strtolower($r['sender_type'])==='customer'?'You':'Store management'?> · <?=e($r['created_at'])?></small><p><?=nl2br(e($r['message']))?></p></div></div><?php endforeach; ?><?php if(!$rows): ?><div class="empty"><h3>Start a private conversation</h3><p>Ask about an order, delivery, product or account issue.</p></div><?php endif; ?></div><form method="post" class="chat-compose"><?=csrf_field()?><textarea name="message" maxlength="4000" required placeholder="Write your private message..."></textarea><button class="btn primary">Send private message</button></form></section><?php require __DIR__.'/../includes/footer.php'; ?>